    PROPERTYCODE = #{propertycode,jdbcType=VARCHAR},
    BALANCE = #{balance,jdbcType=DECIMAL},
    REPORTUUID = #{reportuuid,jdbcType=CHAR}
where DETAILUUID = #{detailuuid,jdbcType=CHAR}

mapper.delete:
delete
from PBC_REPORT_ASSET_CONFIG_DAT prp
